insert into public.listings (owner_id, title, description, price, status, image_url, created_at, updated_at, image_urls,
  category, tags, condition, has_warranty, accessories, pack, size_mm, sale_started_at, stamping, sale_method,
  product_no, ship_info, dial_color, material, has_diamond, reference_no, set_grade, movement, condition_notes)
select '8ae9c0a1-065a-488b-8b06-7ac1a8fd10b1'::uuid, b.title, b.description, b.price, 'on_sale', b.image_urls[1], b.created_at, now(), b.image_urls,
  '벨로르판매', b.tags, b.condition, b.has_warranty, b.accessories, b.pack, b.size_mm, b.created_at, b.stamping,
  '벨로르가 직접 판매하고 결제까지 책임집니다', b.product_no, '결제 후 2~4일 이내 발송', b.dial_color,
  b.material, b.has_diamond, b.reference_no, b.set_grade, b.movement, b.condition_notes
from batch b where not exists (select 1 from public.listings existing where existing.product_no = b.product_no)
returning id, product_no, title, description, price, condition, created_at;

